<template>
  <!-- Your main content with the icon to trigger the popup -->
  <q-icon
    name="info"
    class="cursor-pointer"
    size="18px"
    :color="hasInputError(fieldName) ? 'red' : ''"
  />

  <!-- Popup with hoverable content -->
  <q-tooltip
    class="back-white shadow-1 text-color"
    @before-hide="removeColorFromFields()"
  >
    <div class="max-width-350">
      <div class="text-bold">
        {{
          getFieldLabel(
            formBuilderConfigModel[fieldName],
            '',
          )
        }}
      </div>
      <div>{{ $t('checked_automatically') }}</div>
      <q-separator />
      <div v-if="getLowerConfidence(formBuilderModel[fieldName])">
        <q-icon name="check_circle_outline" color="green" />
        {{ $t('confidence_score') }}:
        <strong>{{ getLowerConfidence(formBuilderModel[fieldName]) }}%</strong>
      </div>
      <q-separator />
      <div class="text-caption text-red" v-if="hasInputError(fieldName)">
        {{ inputErrorMessage() }}
      </div>

      <div
        class="text-caption text-grey"
        v-if="!isDocumentExtratedField(fieldName)"
      >
        {{ $t('SELECT_AREA_NO_COORDINATES') }}
      </div>
      <div
        class="row align-middle"
        v-if="hasAnyFormula() && formulaArrayIsFilled()"
      >
        {{
          getFieldLabel(
            formBuilderConfigModel[fieldName],
            '',
          )
        }}
        =
        <template v-for="(step, index) in getCalculationFields()" :key="index">
          <q-chip
            v-if="isInvoiceField(step)"
            outline
            dense
            :color="fieldColors.get(getFieldName(step))"
            class="chip-design"
            >{{ translateLabel('' + getFieldName(step)) }}</q-chip
          >
          <span class="q-mx-xs" v-else>{{ step }}</span>
        </template>
      </div>
      <div v-if="hasExplanation()">
        <q-separator />
        <div class="text-caption text-grey-8 q-mt-xs">
          <strong>{{ $t('calculation_formula') }}:</strong> {{ getExplanation() }}
        </div>
      </div>
    </div>
  </q-tooltip>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useFormBuilderStore } from 'src/store/main';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { info_panel_chip_colors } from 'src/constants';
import formBuilderHelper from 'src/formBuilder/utils/formBuilderHelper';

export default defineComponent({
  name: 'info-panel',
  mixins: [displayFieldLabel, formBuilderHelper],
  props: {
    fieldName: {
      type: String,
      default: '',
    },
  },
  methods: {
    hasExplanation() {
      const explanationKey = `${this.fieldName}_explanation`;
      const translation = this.$t(explanationKey);
      return translation !== explanationKey;
    },
    getExplanation() {
      return this.$t(`${this.fieldName}_explanation`);
    },
    hasAnyFormula() {
      const hasConfigCalculation =
        !!this.formBuilderConfigModel[this.fieldName].calculation_formula;
      const hasConfigCalculator =
        !!this.formBuilderConfigModel[this.fieldName].calculator_formula;
      const hasModelCalculation =
        !!this.formBuilderModel[this.fieldName].calculation_formula;
      const hasAnyFormula: boolean =
        hasConfigCalculation || hasConfigCalculator || hasModelCalculation;
      return hasAnyFormula;
    },
    isInvoiceField(field_name: string) {
      return field_name.startsWith('[');
    },
    formulaArrayIsFilled() {
      return this.getCalculationFields().length > 0;
    },
    getFormula(): string {
      if (this.formBuilderModel[this.fieldName].calculation_formula) {
         
        return this.formBuilderModel[this.fieldName].calculation_formula;
      }
      if (this.formBuilderConfigModel[this.fieldName].calculation_formula) {
         
        return this.formBuilderConfigModel[this.fieldName].calculation_formula;
      }
      if (this.formBuilderConfigModel[this.fieldName].calculator_formula) {
         
        return this.formBuilderConfigModel[this.fieldName].calculator_formula;
      }
      return '';
    },
    getCalculationFields() {
      let tempStrContainer = '';
      let formulaArray: string[] = [];
      const formula = this.getFormula();
      if (!formula) {
        return formulaArray;
      }
      const tempArray = formula.split(' ');
      for (let index = 0; index < tempArray.length; index = index + 1) {
        tempStrContainer = tempArray[index].trim();
        if (tempArray[index].startsWith('[')) {
          if (tempArray[index] == '[]') {
            continue;
          }
          this.colorField(tempStrContainer);
        }
        formulaArray.push(tempStrContainer);
      }
      return formulaArray;
    },
    inputErrorMessage() {
      let message = '';

      if (!this.formBuilderModel[this.fieldName].input_error) {
        return message;
      }

      const translation_key = this.formBuilderModel[this.fieldName].input_error;
      const translation = this.translateLabel(translation_key);
      message += ' ' + translation + ' ';

      return message;
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      fieldColors,
    } = storeToRefs(form_builder_store);
    const {
      isDocumentExtratedField,
      hasInputError,
      removeColorFromFields,
      getFieldName,
      colorField,
    } = form_builder_store;

    return {
      formBuilderModel,
      fieldColors,
      colorField,
      removeColorFromFields,
      getFieldName,
      isFormBuilderMode,
      formBuilderConfigModel,
      isDocumentExtratedField,
      hasInputError,
      info_panel_chip_colors,
      coloredFields: ref([{} as any]),
    };
  },
});
</script>
