<template>
  <q-icon
    v-if="badgeConfig"
    :name="badgeConfig.icon"
    :class="['extraction-source-badge', badgeConfig.colorClass]"
    size="14px"
  >
    <q-tooltip>{{ badgeConfig.tooltip }}</q-tooltip>
  </q-icon>
</template>

<script lang="ts">
import { defineComponent, computed, PropType } from 'vue';

export interface BadgeConfig {
  icon: string;
  colorClass: string;
  tooltip: string;
}

type ExtractionMethod = 'AI' | 'LEARNED' | 'MD' | 'FELLOW_KV2' | 'ELECTRONIC_DOCUMENT' | string;

export default defineComponent({
  name: 'ExtractionSourceBadge',
  props: {
    extractionMethod: {
      type: String as PropType<ExtractionMethod>,
      default: '',
    },
  },
  setup(props) {
    const badgeConfig = computed((): BadgeConfig | null => {
      if (!props.extractionMethod) {
        return null;
      }

      const method = props.extractionMethod.toUpperCase();

      switch (method) {
        case 'AI':
          return {
            icon: 'mdi-robot',
            colorClass: 'badge-ai',
            tooltip: 'Extracted using AI',
          };
        case 'LEARNED':
          return {
            icon: 'mdi-school',
            colorClass: 'badge-learned',
            tooltip: 'Learned from validated AI extraction',
          };
        case 'MD':
        case 'FELLOW_KV2':
          return {
            icon: 'mdi-database',
            colorClass: 'badge-database',
            tooltip: 'Extracted using saved rules (FELLOW_KV2)',
          };
        case 'ELECTRONIC_DOCUMENT':
          return {
            icon: 'mdi-file-document-outline',
            colorClass: 'badge-electronic',
            tooltip: 'Extracted from electronic document',
          };
        case 'CALCULATED':
          return {
            icon: 'mdi-calculator',
            colorClass: 'badge-calculated',
            tooltip: 'Calculated from vendor master data',
          };
        default:
          return null;
      }
    });

    return {
      badgeConfig,
    };
  },
});
</script>

<style lang="scss" scoped>
.extraction-source-badge {
  margin-left: 4px;
  vertical-align: middle;
  opacity: 0.8;
  cursor: help;

  &:hover {
    opacity: 1;
  }
}

.badge-ai {
  color: #9c27b0; // Purple for AI
}

.badge-learned {
  color: #ff9800; // Orange for Learned
}

.badge-database {
  color: #4caf50; // Green for Database/Rules
}

.badge-electronic {
  color: #2196f3; // Blue for Electronic Document
}

.badge-calculated {
  color: #00897b; // Teal for Calculated fields
}
</style>
